      // themselves in a folder.
      const tag = node.type === "workspace"
        ? T("工作区")
        : node.kind === "folder"
          ? T("文件夹")
          : node.kind === "shortcut"
            ? T("快捷方式")
            : T("特殊文件夹");
      // A workspace and a user folder are the user's own containers, so they can
